"use client";

import { useEffect, useRef } from "react";

import { Scene } from "@babylonjs/core/scene";
import { Engine } from "@babylonjs/core/Engines/engine";
import { Vector3 } from "@babylonjs/core/Maths/math.vector";
import { CubeTexture } from "@babylonjs/core/Materials/Textures/cubeTexture";
import { SceneLoaderFlags } from "@babylonjs/core/Loading/sceneLoaderFlags";
import { HavokPlugin } from "@babylonjs/core/Physics/v2/Plugins/havokPlugin";

import HavokPhysics from "@babylonjs/havok";

import "@babylonjs/core/Loading/loadingScreen";
import "@babylonjs/core/Loading/Plugins/babylonFileLoader";

import "@babylonjs/core/Cameras/universalCamera";

import "@babylonjs/core/Meshes/groundMesh";

import "@babylonjs/core/Lights/directionalLight";
import "@babylonjs/core/Lights/Shadows/shadowGeneratorSceneComponent";

import "@babylonjs/core/Materials/PBR/pbrMaterial";
import "@babylonjs/core/Materials/standardMaterial";
import "@babylonjs/core/XR/features/WebXRDepthSensing";

import "@babylonjs/core/Rendering/depthRendererSceneComponent";
import "@babylonjs/core/Rendering/prePassRendererSceneComponent";

import "@babylonjs/core/Materials/Textures/Loaders/envTextureLoader";
import "@babylonjs/core/Helpers/sceneHelpers";

import "@babylonjs/core/Physics";

import "@babylonjs/materials/sky";

import { getScriptByClassForObject, loadScene } from "babylonjs-editor-tools";

/**
 * We import the map of all scripts attached to objects in the editor.
 * This will allow the loader from `babylonjs-editor-tools` to attach the scripts to the
 * loaded objects (scene, meshes, transform nodes, lights, cameras, etc.).
 */
import { scriptsMap } from "@/scripts";
import ControlManager from "@/scripts/TurntableManager";

export default function Home() {
	const canvasRef = useRef<HTMLCanvasElement>(null);

	useEffect(() => {
		if (!canvasRef.current) {
			return;
		}

		const engine = new Engine(canvasRef.current, true, {
			stencil: true,
			antialias: true,
			audioEngine: true,
			adaptToDeviceRatio: true,
			disableWebGL2Support: false,
			useHighPrecisionFloats: true,
			powerPreference: "high-performance",
			failIfMajorPerformanceCaveat: false,
		});
		engine.loadingScreen = {
			displayLoadingUI: () => undefined,
			hideLoadingUI: () => undefined,
			loadingUIBackgroundColor: "transparent",
			loadingUIText: "",
		};

		const scene = new Scene(engine);

		handleLoad(engine, scene, canvasRef.current);

		let listener: () => void;
		window.addEventListener("resize", listener = () => {
			engine.resize();
		});

		return () => {
			scene.dispose();
			engine.dispose();

			window.removeEventListener("resize", listener);
		};
	}, [canvasRef]);

	async function handleLoad(engine: Engine, scene: Scene, canvas: HTMLCanvasElement) {
		const havok = await HavokPhysics();
		scene.enablePhysics(new Vector3(0, -981, 0), new HavokPlugin(true, havok));

		SceneLoaderFlags.ForceFullSceneLoadingForIncremental = true;
		await loadScene("/scene/", "DownloadExample.babylon", scene, scriptsMap, {
			quality: "high",
		});

		const environmentTexture = CubeTexture.CreateFromPrefilteredData(
			"/scene/assets/panoramic_background-exr_00000.env",
			scene
		);
		scene.environmentTexture = environmentTexture;
		scene.createDefaultSkybox(environmentTexture, true, 10000, 0.9);

		const controlManagerNode = scene.getTransformNodeByName("ControlManager");
		const controlManager = controlManagerNode
			? getScriptByClassForObject(controlManagerNode, ControlManager) ?? new ControlManager(scene)
			: new ControlManager(scene);
		controlManager.createTurntableCamera(canvas);

		engine.runRenderLoop(() => {
			scene.render();
		});
	}

	return (
		<main className="flex w-screen h-screen flex-col items-center justify-between">
			<canvas
				ref={canvasRef}
				className="w-full h-full outline-none select-none touch-none"
				onContextMenu={(event) => event.preventDefault()}
			/>
		</main>
	);
}
